begin;

create type academic.schedule_resource_status as enum ('DRAFT','ACTIVE','INACTIVE','RETIRED');
create type academic.academic_space_type as enum ('CLASSROOM','LABORATORY','WORKSHOP','MULTIPURPOSE','OTHER');
create type academic.academic_space_status as enum ('DRAFT','ACTIVE','MAINTENANCE','INACTIVE','RETIRED');
create type academic.accessibility_notes_code as enum ('ACCESSIBLE','LIMITED_ACCESS','NOT_ACCESSIBLE','NOT_ASSESSED');
create type academic.schedule_template_status as enum ('DRAFT','UNDER_REVIEW','APPROVED','ACTIVE','RETIRED','CANCELLED');
create type academic.template_block_status as enum ('ACTIVE','INACTIVE');
create type academic.teacher_availability_type as enum ('AVAILABLE','UNAVAILABLE','PREFERRED');
create type academic.teacher_availability_status as enum ('ACTIVE','CANCELLED');
create type academic.group_schedule_status as enum ('DRAFT','UNDER_REVIEW','APPROVED','PUBLISHED','CLOSED','CANCELLED');
create type academic.class_session_type as enum ('REGULAR_CLASS','LABORATORY','WORKSHOP');
create type academic.class_session_status as enum ('PLANNED','ACTIVE','CANCELLED','ENDED');
create type academic.schedule_change_type as enum ('SESSION_ADD','SESSION_MOVE','SESSION_SPACE_CHANGE','SESSION_TEACHER_CHANGE','SESSION_CANCEL','SCHEDULE_REPLACEMENT');
create type academic.schedule_change_status as enum ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','APPLIED','CANCELLED','EXPIRED');
create type academic.schedule_reason_code as enum ('INITIAL_CONFIGURATION','SCHEDULE_OPERATION','INSTITUTIONAL_APPROVAL','CORRECTIVE_CHANGE','VALIDATION_REJECTED');
create type academic.schedule_entity_type as enum ('SHIFT','SPACE','TIME_BLOCK','TEMPLATE','TEACHER_AVAILABILITY','GROUP_SCHEDULE','CLASS_SESSION','SCHEDULE_CHANGE');
create type academic.schedule_command_status as enum ('IN_PROGRESS','COMPLETED','FAILED');
create type academic.schedule_command_type as enum (
 'CREATE_ACADEMIC_SHIFT','ACTIVATE_ACADEMIC_SHIFT','DEACTIVATE_ACADEMIC_SHIFT','RETIRE_ACADEMIC_SHIFT',
 'CREATE_ACADEMIC_SPACE','ACTIVATE_ACADEMIC_SPACE','MARK_ACADEMIC_SPACE_MAINTENANCE','DEACTIVATE_ACADEMIC_SPACE','REACTIVATE_ACADEMIC_SPACE','RETIRE_ACADEMIC_SPACE',
 'CREATE_SCHEDULE_TIME_BLOCK','ACTIVATE_SCHEDULE_TIME_BLOCK','DEACTIVATE_SCHEDULE_TIME_BLOCK',
 'CREATE_SCHEDULE_TEMPLATE','ADD_SCHEDULE_TEMPLATE_BLOCK','SUBMIT_SCHEDULE_TEMPLATE','APPROVE_SCHEDULE_TEMPLATE','ACTIVATE_SCHEDULE_TEMPLATE','RETIRE_SCHEDULE_TEMPLATE',
 'DECLARE_TEACHER_AVAILABILITY','CANCEL_TEACHER_AVAILABILITY',
 'CREATE_GROUP_SCHEDULE','SUBMIT_GROUP_SCHEDULE','APPROVE_GROUP_SCHEDULE','PUBLISH_GROUP_SCHEDULE','CLOSE_GROUP_SCHEDULE','CANCEL_GROUP_SCHEDULE',
 'CREATE_CLASS_SESSION','ACTIVATE_CLASS_SESSION','MOVE_CLASS_SESSION','CHANGE_CLASS_SESSION_SPACE','CHANGE_CLASS_SESSION_ASSIGNMENT','CANCEL_CLASS_SESSION','END_CLASS_SESSION',
 'CREATE_SCHEDULE_CHANGE_REQUEST','SUBMIT_SCHEDULE_CHANGE_REQUEST','BEGIN_SCHEDULE_CHANGE_REVIEW','APPROVE_SCHEDULE_CHANGE_REQUEST','REJECT_SCHEDULE_CHANGE_REQUEST','APPLY_SCHEDULE_CHANGE_REQUEST','CANCEL_SCHEDULE_CHANGE_REQUEST'
);
create type academic.schedule_event_type as enum (
 'SHIFT_CREATED','SHIFT_ACTIVATED','SHIFT_DEACTIVATED','SHIFT_RETIRED','SPACE_CREATED','SPACE_ACTIVATED','SPACE_MAINTENANCE_STARTED','SPACE_DEACTIVATED','SPACE_REACTIVATED','SPACE_RETIRED','TIME_BLOCK_CREATED','TIME_BLOCK_ACTIVATED','TIME_BLOCK_DEACTIVATED','TEMPLATE_CREATED','TEMPLATE_BLOCK_ADDED','TEMPLATE_SUBMITTED','TEMPLATE_APPROVED','TEMPLATE_ACTIVATED','TEMPLATE_RETIRED','TEACHER_AVAILABILITY_DECLARED','TEACHER_AVAILABILITY_CANCELLED','GROUP_SCHEDULE_CREATED','GROUP_SCHEDULE_SUBMITTED','GROUP_SCHEDULE_APPROVED','GROUP_SCHEDULE_PUBLISHED','GROUP_SCHEDULE_CLOSED','GROUP_SCHEDULE_CANCELLED','CLASS_SESSION_CREATED','CLASS_SESSION_ACTIVATED','CLASS_SESSION_MOVED','CLASS_SESSION_SPACE_CHANGED','CLASS_SESSION_ASSIGNMENT_CHANGED','CLASS_SESSION_CANCELLED','CLASS_SESSION_ENDED','SCHEDULE_CHANGE_REQUESTED','SCHEDULE_CHANGE_SUBMITTED','SCHEDULE_CHANGE_REVIEW_STARTED','SCHEDULE_CHANGE_APPROVED','SCHEDULE_CHANGE_REJECTED','SCHEDULE_CHANGE_APPLIED','SCHEDULE_CHANGE_CANCELLED','SCHEDULE_CONFLICT_REJECTED'
);

revoke usage on type academic.schedule_resource_status,academic.academic_space_type,academic.academic_space_status,academic.accessibility_notes_code,academic.schedule_template_status,academic.template_block_status,academic.teacher_availability_type,academic.teacher_availability_status,academic.group_schedule_status,academic.class_session_type,academic.class_session_status,academic.schedule_change_type,academic.schedule_change_status,academic.schedule_reason_code,academic.schedule_entity_type,academic.schedule_command_status,academic.schedule_command_type,academic.schedule_event_type from public,anon,authenticated;

create table academic.academic_shifts(
 id uuid primary key default gen_random_uuid(), code academic.normalized_code not null unique, name text not null check(char_length(btrim(name)) between 2 and 120),
 starts_at time not null, ends_at time not null, status academic.schedule_resource_status not null default 'DRAFT', created_by_account_id uuid not null references core.accounts(id) on delete restrict,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(starts_at<ends_at)
);
create table academic.academic_spaces(
 id uuid primary key default gen_random_uuid(), code academic.normalized_code not null unique, name text not null check(char_length(btrim(name)) between 2 and 120), building_code text check(building_code is null or char_length(btrim(building_code)) between 1 and 40), floor_label text check(floor_label is null or char_length(btrim(floor_label)) between 1 and 40),
 space_type academic.academic_space_type not null, capacity integer check(capacity is null or capacity>0), status academic.academic_space_status not null default 'DRAFT', accessibility_notes_code academic.accessibility_notes_code,
 created_by_account_id uuid not null references core.accounts(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table academic.schedule_time_blocks(
 id uuid primary key default gen_random_uuid(), shift_id uuid not null references academic.academic_shifts(id) on delete restrict, code academic.normalized_code not null, display_name text not null check(char_length(btrim(display_name)) between 2 and 80), sequence_number smallint not null check(sequence_number>0), starts_at time not null, ends_at time not null,
 is_first_period boolean not null default false, is_break boolean not null default false, status academic.schedule_resource_status not null default 'DRAFT', created_by_account_id uuid not null references core.accounts(id) on delete restrict,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(shift_id,code), unique(shift_id,sequence_number), check(starts_at<ends_at), check(not(is_first_period and is_break))
);
create unique index schedule_time_blocks_one_first_active on academic.schedule_time_blocks(shift_id) where is_first_period and status='ACTIVE';

create table academic.schedule_templates(
 id uuid primary key default gen_random_uuid(), code academic.normalized_code not null unique, name text not null check(char_length(btrim(name)) between 2 and 120), shift_id uuid not null references academic.academic_shifts(id) on delete restrict,
 status academic.schedule_template_status not null default 'DRAFT', valid_from date, valid_to date, created_by_account_id uuid not null references core.accounts(id) on delete restrict, approved_by_account_id uuid references core.accounts(id) on delete restrict,
 created_at timestamptz not null default now(), approved_at timestamptz, updated_at timestamptz not null default now(), check(valid_to is null or valid_from is null or valid_to>=valid_from)
);
create table academic.schedule_template_blocks(
 id uuid primary key default gen_random_uuid(), schedule_template_id uuid not null references academic.schedule_templates(id) on delete restrict, weekday smallint not null check(weekday between 1 and 7), time_block_id uuid not null references academic.schedule_time_blocks(id) on delete restrict,
 status academic.template_block_status not null default 'ACTIVE', created_at timestamptz not null default now(), unique(schedule_template_id,weekday,time_block_id)
);
create table academic.teacher_availability(
 id uuid primary key default gen_random_uuid(), teacher_account_id uuid not null references core.accounts(id) on delete restrict, academic_period_id uuid not null references academic.academic_periods(id) on delete restrict,
 weekday smallint not null check(weekday between 1 and 7), time_block_id uuid not null references academic.schedule_time_blocks(id) on delete restrict, availability_type academic.teacher_availability_type not null, status academic.teacher_availability_status not null default 'ACTIVE',
 valid_from date, valid_to date, declared_by_account_id uuid not null references core.accounts(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(valid_to is null or valid_from is null or valid_to>=valid_from)
);
create unique index teacher_availability_active_unique on academic.teacher_availability(teacher_account_id,academic_period_id,weekday,time_block_id) where status='ACTIVE';

create table academic.group_schedules(
 id uuid primary key default gen_random_uuid(), group_id uuid not null references academic.groups(id) on delete restrict, academic_period_id uuid not null references academic.academic_periods(id) on delete restrict, schedule_template_id uuid not null references academic.schedule_templates(id) on delete restrict,
 status academic.group_schedule_status not null default 'DRAFT', version_number integer not null check(version_number>0), effective_from date, effective_to date,
 created_by_account_id uuid not null references core.accounts(id) on delete restrict, submitted_by_account_id uuid references core.accounts(id) on delete restrict, approved_by_account_id uuid references core.accounts(id) on delete restrict, published_by_account_id uuid references core.accounts(id) on delete restrict, closed_by_account_id uuid references core.accounts(id) on delete restrict,
 created_at timestamptz not null default now(), submitted_at timestamptz, approved_at timestamptz, published_at timestamptz, closed_at timestamptz, updated_at timestamptz not null default now(), unique(group_id,version_number), check(effective_to is null or effective_from is null or effective_to>=effective_from)
);
create unique index group_schedules_one_published on academic.group_schedules(group_id) where status='PUBLISHED';
create table academic.class_sessions(
 id uuid primary key default gen_random_uuid(), group_schedule_id uuid not null references academic.group_schedules(id) on delete restrict, academic_offering_id uuid not null references academic.academic_offerings(id) on delete restrict, teaching_assignment_id uuid not null references academic.teaching_assignments(id) on delete restrict,
 academic_space_id uuid not null references academic.academic_spaces(id) on delete restrict, weekday smallint not null check(weekday between 1 and 7), time_block_id uuid not null references academic.schedule_time_blocks(id) on delete restrict, session_type academic.class_session_type not null, status academic.class_session_status not null default 'PLANNED',
 valid_from date, valid_to date, created_by_account_id uuid not null references core.accounts(id) on delete restrict, cancelled_by_account_id uuid references core.accounts(id) on delete restrict, created_at timestamptz not null default now(), cancelled_at timestamptz, updated_at timestamptz not null default now(), check(valid_to is null or valid_from is null or valid_to>=valid_from)
);
create unique index class_sessions_group_slot_unique on academic.class_sessions(group_schedule_id,weekday,time_block_id) where status in ('PLANNED','ACTIVE');
create index class_sessions_assignment_slot_idx on academic.class_sessions(teaching_assignment_id,weekday,time_block_id) where status in ('PLANNED','ACTIVE');
create index class_sessions_space_slot_idx on academic.class_sessions(academic_space_id,weekday,time_block_id) where status in ('PLANNED','ACTIVE');

create table academic.schedule_change_requests(
 id uuid primary key default gen_random_uuid(), group_schedule_id uuid not null references academic.group_schedules(id) on delete restrict, request_type academic.schedule_change_type not null, status academic.schedule_change_status not null default 'DRAFT', reason_code academic.schedule_reason_code not null,
 requested_by_account_id uuid not null references core.accounts(id) on delete restrict, reviewed_by_account_id uuid references core.accounts(id) on delete restrict, approved_by_account_id uuid references core.accounts(id) on delete restrict, applied_by_account_id uuid references core.accounts(id) on delete restrict,
 idempotency_key text not null check(char_length(idempotency_key) between 8 and 120), request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'), requested_at timestamptz not null default now(), reviewed_at timestamptz, approved_at timestamptz, applied_at timestamptz, rejected_at timestamptz, cancelled_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(requested_by_account_id,idempotency_key)
);
create table academic.schedule_commands(
 id uuid primary key default gen_random_uuid(), actor_account_id uuid not null references core.accounts(id) on delete restrict, command_type academic.schedule_command_type not null, idempotency_key text not null check(char_length(idempotency_key) between 8 and 120), request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'),
 resulting_entity_type academic.schedule_entity_type, resulting_entity_id uuid, status academic.schedule_command_status not null default 'IN_PROGRESS', created_at timestamptz not null default now(), completed_at timestamptz, unique(actor_account_id,command_type,idempotency_key), check((status='COMPLETED')=(completed_at is not null and resulting_entity_id is not null))
);
create table academic.schedule_events(
 id uuid primary key default gen_random_uuid(), entity_type academic.schedule_entity_type not null, entity_id uuid not null, group_schedule_id uuid references academic.group_schedules(id) on delete restrict, academic_period_id uuid references academic.academic_periods(id) on delete restrict,
 event_type academic.schedule_event_type not null, actor_account_id uuid not null references core.accounts(id) on delete restrict, previous_status text, resulting_status text, reason_code academic.schedule_reason_code not null, idempotency_key text not null, correlation_id uuid, occurred_at timestamptz not null default now(), unique(actor_account_id,event_type,idempotency_key)
);

create index schedule_template_blocks_template_idx on academic.schedule_template_blocks(schedule_template_id);
create index teacher_availability_period_teacher_idx on academic.teacher_availability(academic_period_id,teacher_account_id);
create index group_schedules_period_group_idx on academic.group_schedules(academic_period_id,group_id);
create index class_sessions_schedule_idx on academic.class_sessions(group_schedule_id);
create index schedule_change_requests_schedule_idx on academic.schedule_change_requests(group_schedule_id,requested_at desc);
create index schedule_events_entity_idx on academic.schedule_events(entity_type,entity_id,occurred_at desc);

do $$declare n text; begin foreach n in array array['academic_shifts','academic_spaces','schedule_time_blocks','schedule_templates','schedule_template_blocks','teacher_availability','group_schedules','class_sessions','schedule_change_requests','schedule_commands','schedule_events'] loop execute format('alter table academic.%I enable row level security',n); execute format('revoke all on table academic.%I from public,anon,authenticated',n); end loop; end$$;

create function academic.require_schedule_permission(permission_code text) returns uuid language plpgsql stable security definer set search_path='' as $$
declare actor core.accounts%rowtype; role_codes text[]; allowed boolean:=false;
begin
 if permission_code not in ('academic.shifts.read','academic.shifts.manage','academic.spaces.read','academic.spaces.manage','academic.time_blocks.read','academic.time_blocks.manage','academic.schedule_templates.read','academic.schedule_templates.manage','academic.schedules.read','academic.schedules.manage','academic.schedules.approve','academic.schedules.publish','academic.teacher_availability.read','academic.teacher_availability.manage','academic.workload.read','academic.schedule_changes.manage','academic.schedule_changes.approve') then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 if auth.uid() is null then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 select * into actor from core.accounts where auth_user_id=auth.uid();
 if actor.id is null or actor.account_status<>'ACTIVE' or not core.is_current_session_version_valid() then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 if not core.is_current_aal2() or not core.is_current_mfa_policy_satisfied() then raise exception using errcode='42501',message='AAL2_REQUIRED'; end if;
 select coalesce(array_agg(r.code),array[]::text[]) into role_codes from core.account_roles ar join core.roles r on r.id=ar.role_id and r.is_active where ar.account_id=actor.id and ar.revoked_at is null;
 if role_codes&&array['SUPERADMIN','ADMINISTRATIVO'] then allowed:=true;
 elsif role_codes&&array['CONTROL_ESCOLAR'] then allowed:=permission_code in ('academic.schedules.read','academic.schedules.manage','academic.schedules.approve','academic.schedules.publish','academic.teacher_availability.read','academic.teacher_availability.manage','academic.workload.read','academic.schedule_changes.manage','academic.schedule_changes.approve'); end if;
 if not allowed then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if; return actor.id;
end$$;

create function academic.schedule_fingerprint(payload jsonb) returns text language sql immutable security invoker set search_path='' as $$select encode(extensions.digest(payload::text,'sha256'),'hex')$$;
create function academic.begin_schedule_command(actor_id uuid,command_name academic.schedule_command_type,operation_key text,payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare prior academic.schedule_commands%rowtype; fingerprint text:=academic.schedule_fingerprint(payload);
begin
 if operation_key is null or char_length(operation_key) not between 8 and 120 then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
 perform pg_advisory_xact_lock(hashtextextended(actor_id::text||command_name::text||operation_key,0));
 select * into prior from academic.schedule_commands where actor_account_id=actor_id and command_type=command_name and idempotency_key=operation_key for update;
 if prior.id is not null then if prior.request_fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_CONFLICT'; end if; return prior.resulting_entity_id; end if;
 insert into academic.schedule_commands(actor_account_id,command_type,idempotency_key,request_fingerprint) values(actor_id,command_name,operation_key,fingerprint); return null;
end$$;
create function academic.complete_schedule_command(actor_id uuid,command_name academic.schedule_command_type,operation_key text,entity_type academic.schedule_entity_type,entity_id uuid) returns void language sql security definer set search_path='' as $$update academic.schedule_commands set status='COMPLETED',resulting_entity_type=entity_type,resulting_entity_id=entity_id,completed_at=statement_timestamp() where actor_account_id=actor_id and command_type=command_name and idempotency_key=operation_key$$;
create function academic.append_schedule_event(entity_type academic.schedule_entity_type,entity_id uuid,schedule_id uuid,period_id uuid,event_type academic.schedule_event_type,actor_id uuid,previous_status text,resulting_status text,reason academic.schedule_reason_code,operation_key text,correlation uuid) returns void language sql security definer set search_path='' as $$insert into academic.schedule_events(entity_type,entity_id,group_schedule_id,academic_period_id,event_type,actor_account_id,previous_status,resulting_status,reason_code,idempotency_key,correlation_id) values(entity_type,entity_id,schedule_id,period_id,event_type,actor_id,previous_status,resulting_status,reason,operation_key,correlation)$$;

create function academic.valid_shift_transition(old academic.schedule_resource_status,new academic.schedule_resource_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,new) in (('DRAFT','ACTIVE'),('ACTIVE','INACTIVE'),('INACTIVE','ACTIVE'),('ACTIVE','RETIRED'),('INACTIVE','RETIRED'))$$;
create function academic.valid_space_transition(old academic.academic_space_status,new academic.academic_space_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,new) in (('DRAFT','ACTIVE'),('ACTIVE','MAINTENANCE'),('MAINTENANCE','ACTIVE'),('ACTIVE','INACTIVE'),('MAINTENANCE','INACTIVE'),('INACTIVE','ACTIVE'),('ACTIVE','RETIRED'),('INACTIVE','RETIRED'))$$;
create function academic.valid_template_transition(old academic.schedule_template_status,new academic.schedule_template_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,new) in (('DRAFT','UNDER_REVIEW'),('UNDER_REVIEW','APPROVED'),('APPROVED','ACTIVE'),('ACTIVE','RETIRED'),('DRAFT','CANCELLED'),('UNDER_REVIEW','CANCELLED'))$$;
create function academic.valid_group_schedule_transition(old academic.group_schedule_status,new academic.group_schedule_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,new) in (('DRAFT','UNDER_REVIEW'),('UNDER_REVIEW','APPROVED'),('APPROVED','PUBLISHED'),('PUBLISHED','CLOSED'),('DRAFT','CANCELLED'),('UNDER_REVIEW','CANCELLED'))$$;
create function academic.valid_class_session_transition(old academic.class_session_status,new academic.class_session_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,new) in (('PLANNED','ACTIVE'),('PLANNED','CANCELLED'),('ACTIVE','ENDED'),('ACTIVE','CANCELLED'))$$;
create function academic.valid_schedule_change_transition(old academic.schedule_change_status,new academic.schedule_change_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,new) in (('DRAFT','SUBMITTED'),('SUBMITTED','UNDER_REVIEW'),('UNDER_REVIEW','APPROVED'),('UNDER_REVIEW','REJECTED'),('APPROVED','APPLIED'),('DRAFT','CANCELLED'),('SUBMITTED','CANCELLED'),('SUBMITTED','EXPIRED'),('UNDER_REVIEW','EXPIRED'))$$;

create function academic.guard_schedule_history() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if current_setting('academic.schedule_controlled_mutation',true)='on' then return new; end if;
 if tg_op='DELETE' then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='schedule_events' then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='schedule_commands' and old.status::text='COMPLETED' and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='academic_shifts' and old.status::text='RETIRED' and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='academic_spaces' and old.status::text='RETIRED' and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='schedule_templates' and old.status::text in ('APPROVED','ACTIVE','RETIRED') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='group_schedules' and old.status::text in ('PUBLISHED','CLOSED','CANCELLED') and new is distinct from old then raise exception 'PUBLISHED_SCHEDULE_IMMUTABLE'; end if;
 if tg_table_name='class_sessions' and old.status::text in ('ENDED','CANCELLED') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='schedule_change_requests' and old.status::text in ('APPLIED','REJECTED','EXPIRED','CANCELLED') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 return new; end$$;
do $$declare n text; begin foreach n in array array['academic_shifts','academic_spaces','schedule_time_blocks','schedule_templates','schedule_template_blocks','teacher_availability','group_schedules','class_sessions','schedule_change_requests','schedule_commands','schedule_events'] loop execute format('create trigger %I_schedule_history before update or delete on academic.%I for each row execute function academic.guard_schedule_history()',n,n); end loop; end$$;

create function academic.create_academic_shift(shift_code text,shift_name text,start_time time,end_time time,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; begin actor:=academic.require_schedule_permission('academic.shifts.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_ACADEMIC_SHIFT',operation_key,jsonb_build_object('code',upper(btrim(shift_code)),'name',btrim(shift_name),'starts',start_time,'ends',end_time)); if prior is not null then return query select prior,'DRAFT'; return; end if; if start_time>=end_time then raise exception 'SHIFT_TIME_RANGE_INVALID'; end if; insert into academic.academic_shifts(code,name,starts_at,ends_at,created_by_account_id) values(upper(btrim(shift_code)),btrim(shift_name),start_time,end_time,actor) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_ACADEMIC_SHIFT',operation_key,'SHIFT',created); perform academic.append_schedule_event('SHIFT',created,null,null,'SHIFT_CREATED',actor,null,'DRAFT','INITIAL_CONFIGURATION',operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.change_shift_status(shift_id uuid,target academic.schedule_resource_status,command_name academic.schedule_command_type,event academic.schedule_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; old academic.schedule_resource_status; begin actor:=academic.require_schedule_permission('academic.shifts.manage'); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('shift',shift_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select s.status into old from academic.academic_shifts s where id=shift_id for update; if old is null then raise exception 'SHIFT_NOT_FOUND'; end if; if not academic.valid_shift_transition(old,target) then raise exception 'SHIFT_INVALID_STATE'; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.academic_shifts set status=target,updated_at=statement_timestamp() where id=shift_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'SHIFT',shift_id); perform academic.append_schedule_event('SHIFT',shift_id,null,null,event,actor,old::text,target::text,'SCHEDULE_OPERATION',operation_key,correlation); return query select shift_id,target::text; end$$;
create function academic.activate_academic_shift(shift_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_shift_status(shift_id,'ACTIVE','ACTIVATE_ACADEMIC_SHIFT','SHIFT_ACTIVATED',operation_key,correlation)$$;
create function academic.deactivate_academic_shift(shift_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_shift_status(shift_id,'INACTIVE','DEACTIVATE_ACADEMIC_SHIFT','SHIFT_DEACTIVATED',operation_key,correlation)$$;
create function academic.retire_academic_shift(shift_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_shift_status(shift_id,'RETIRED','RETIRE_ACADEMIC_SHIFT','SHIFT_RETIRED',operation_key,correlation)$$;

create function academic.create_academic_space(space_code text,space_name text,kind academic.academic_space_type,space_capacity integer,building text,floor_name text,accessibility academic.accessibility_notes_code,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; begin actor:=academic.require_schedule_permission('academic.spaces.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_ACADEMIC_SPACE',operation_key,jsonb_build_object('code',upper(btrim(space_code)),'name',btrim(space_name),'kind',kind,'capacity',space_capacity,'building',building,'floor',floor_name,'accessibility',accessibility)); if prior is not null then return query select prior,'DRAFT'; return; end if; if space_capacity is not null and space_capacity<=0 then raise exception 'SPACE_CAPACITY_INVALID'; end if; insert into academic.academic_spaces(code,name,space_type,capacity,building_code,floor_label,accessibility_notes_code,created_by_account_id) values(upper(btrim(space_code)),btrim(space_name),kind,space_capacity,nullif(btrim(building),''),nullif(btrim(floor_name),''),accessibility,actor) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_ACADEMIC_SPACE',operation_key,'SPACE',created); perform academic.append_schedule_event('SPACE',created,null,null,'SPACE_CREATED',actor,null,'DRAFT','INITIAL_CONFIGURATION',operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.change_space_status(space_id uuid,target academic.academic_space_status,command_name academic.schedule_command_type,event academic.schedule_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; old academic.academic_space_status; begin actor:=academic.require_schedule_permission('academic.spaces.manage'); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('space',space_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select s.status into old from academic.academic_spaces s where id=space_id for update; if old is null then raise exception 'SPACE_NOT_FOUND'; end if; if not academic.valid_space_transition(old,target) then raise exception 'INVALID_STATE_TRANSITION'; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.academic_spaces set status=target,updated_at=statement_timestamp() where id=space_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'SPACE',space_id); perform academic.append_schedule_event('SPACE',space_id,null,null,event,actor,old::text,target::text,'SCHEDULE_OPERATION',operation_key,correlation); return query select space_id,target::text; end$$;
create function academic.activate_academic_space(space_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_space_status(space_id,'ACTIVE','ACTIVATE_ACADEMIC_SPACE','SPACE_ACTIVATED',operation_key,correlation)$$;
create function academic.mark_academic_space_maintenance(space_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_space_status(space_id,'MAINTENANCE','MARK_ACADEMIC_SPACE_MAINTENANCE','SPACE_MAINTENANCE_STARTED',operation_key,correlation)$$;
create function academic.deactivate_academic_space(space_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_space_status(space_id,'INACTIVE','DEACTIVATE_ACADEMIC_SPACE','SPACE_DEACTIVATED',operation_key,correlation)$$;
create function academic.reactivate_academic_space(space_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_space_status(space_id,'ACTIVE','REACTIVATE_ACADEMIC_SPACE','SPACE_REACTIVATED',operation_key,correlation)$$;
create function academic.retire_academic_space(space_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_space_status(space_id,'RETIRED','RETIRE_ACADEMIC_SPACE','SPACE_RETIRED',operation_key,correlation)$$;

create function academic.create_schedule_time_block(shift_id uuid,block_code text,block_name text,sequence smallint,start_time time,end_time time,first_period boolean,is_recess boolean,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; shift_status academic.schedule_resource_status; begin actor:=academic.require_schedule_permission('academic.time_blocks.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_SCHEDULE_TIME_BLOCK',operation_key,jsonb_build_object('shift',shift_id,'code',upper(btrim(block_code)),'sequence',sequence,'starts',start_time,'ends',end_time,'first',first_period,'break',is_recess)); if prior is not null then return query select prior,'DRAFT'; return; end if; select s.status into shift_status from academic.academic_shifts s where s.id=shift_id for update; if shift_status is null then raise exception 'SHIFT_NOT_FOUND'; end if; if sequence<=0 or start_time>=end_time or first_period and is_recess then raise exception 'TIME_BLOCK_CONFLICT'; end if; if exists(select 1 from academic.schedule_time_blocks b where b.shift_id=create_schedule_time_block.shift_id and b.status='ACTIVE' and b.starts_at<end_time and start_time<b.ends_at) then raise exception 'TIME_BLOCK_CONFLICT'; end if; if first_period and exists(select 1 from academic.schedule_time_blocks b where b.shift_id=create_schedule_time_block.shift_id and b.is_first_period and b.status='ACTIVE') then raise exception 'FIRST_PERIOD_CONFLICT'; end if; insert into academic.schedule_time_blocks(shift_id,code,display_name,sequence_number,starts_at,ends_at,is_first_period,is_break,created_by_account_id) values(shift_id,upper(btrim(block_code)),btrim(block_name),sequence,start_time,end_time,first_period,is_recess,actor) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_SCHEDULE_TIME_BLOCK',operation_key,'TIME_BLOCK',created); perform academic.append_schedule_event('TIME_BLOCK',created,null,null,'TIME_BLOCK_CREATED',actor,null,'DRAFT','INITIAL_CONFIGURATION',operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.change_time_block_status(block_id uuid,target academic.schedule_resource_status,command_name academic.schedule_command_type,event academic.schedule_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; block academic.schedule_time_blocks%rowtype; begin actor:=academic.require_schedule_permission('academic.time_blocks.manage'); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('block',block_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into block from academic.schedule_time_blocks where id=block_id for update; if block.id is null then raise exception 'TIME_BLOCK_NOT_FOUND'; end if; if not ((block.status,target) in (('DRAFT','ACTIVE'),('ACTIVE','INACTIVE'))) then raise exception 'INVALID_STATE_TRANSITION'; end if; if target='ACTIVE' and exists(select 1 from academic.schedule_time_blocks b where b.shift_id=block.shift_id and b.id<>block.id and b.status='ACTIVE' and b.starts_at<block.ends_at and block.starts_at<b.ends_at) then raise exception 'TIME_BLOCK_CONFLICT'; end if; if target='ACTIVE' and block.is_first_period and exists(select 1 from academic.schedule_time_blocks b where b.shift_id=block.shift_id and b.id<>block.id and b.status='ACTIVE' and b.is_first_period) then raise exception 'FIRST_PERIOD_CONFLICT'; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.schedule_time_blocks set status=target,updated_at=statement_timestamp() where id=block_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'TIME_BLOCK',block_id); perform academic.append_schedule_event('TIME_BLOCK',block_id,null,null,event,actor,block.status::text,target::text,'SCHEDULE_OPERATION',operation_key,correlation); return query select block_id,target::text; end$$;
create function academic.activate_schedule_time_block(block_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_time_block_status(block_id,'ACTIVE','ACTIVATE_SCHEDULE_TIME_BLOCK','TIME_BLOCK_ACTIVATED',operation_key,correlation)$$;
create function academic.deactivate_schedule_time_block(block_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_time_block_status(block_id,'INACTIVE','DEACTIVATE_SCHEDULE_TIME_BLOCK','TIME_BLOCK_DEACTIVATED',operation_key,correlation)$$;

create function academic.create_schedule_template(template_code text,template_name text,shift_id uuid,valid_from date,valid_to date,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; shift_status academic.schedule_resource_status; begin actor:=academic.require_schedule_permission('academic.schedule_templates.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_SCHEDULE_TEMPLATE',operation_key,jsonb_build_object('code',upper(btrim(template_code)),'name',btrim(template_name),'shift',shift_id,'from',valid_from,'to',valid_to)); if prior is not null then return query select prior,'DRAFT'; return; end if; select s.status into shift_status from academic.academic_shifts s where s.id=shift_id for update; if shift_status<>'ACTIVE' then raise exception 'SHIFT_INVALID_STATE'; end if; insert into academic.schedule_templates(code,name,shift_id,valid_from,valid_to,created_by_account_id) values(upper(btrim(template_code)),btrim(template_name),shift_id,valid_from,valid_to,actor) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_SCHEDULE_TEMPLATE',operation_key,'TEMPLATE',created); perform academic.append_schedule_event('TEMPLATE',created,null,null,'TEMPLATE_CREATED',actor,null,'DRAFT','INITIAL_CONFIGURATION',operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.add_schedule_template_block(template_id uuid,weekday smallint,block_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; template academic.schedule_templates%rowtype; block academic.schedule_time_blocks%rowtype; begin actor:=academic.require_schedule_permission('academic.schedule_templates.manage'); prior:=academic.begin_schedule_command(actor,'ADD_SCHEDULE_TEMPLATE_BLOCK',operation_key,jsonb_build_object('template',template_id,'weekday',weekday,'block',block_id)); if prior is not null then return query select prior,'ACTIVE'; return; end if; select * into template from academic.schedule_templates where id=template_id for update; select * into block from academic.schedule_time_blocks where id=block_id for update; if template.id is null then raise exception 'TEMPLATE_NOT_FOUND'; end if; if template.status<>'DRAFT' then raise exception 'TEMPLATE_INVALID_STATE'; end if; if weekday not between 1 and 7 or block.id is null or block.shift_id<>template.shift_id or block.status<>'ACTIVE' or block.is_break then raise exception 'TEMPLATE_BLOCK_NOT_ALLOWED'; end if; insert into academic.schedule_template_blocks(schedule_template_id,weekday,time_block_id) values(template_id,weekday,block_id) returning id into created; perform academic.complete_schedule_command(actor,'ADD_SCHEDULE_TEMPLATE_BLOCK',operation_key,'TEMPLATE',created); perform academic.append_schedule_event('TEMPLATE',template_id,null,null,'TEMPLATE_BLOCK_ADDED',actor,'DRAFT','DRAFT','SCHEDULE_OPERATION',operation_key,correlation); return query select created,'ACTIVE'; end$$;
create function academic.change_template_status(template_id uuid,target academic.schedule_template_status,command_name academic.schedule_command_type,event academic.schedule_event_type,permission text,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; old academic.schedule_template_status; begin actor:=academic.require_schedule_permission(permission); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('template',template_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select t.status into old from academic.schedule_templates t where id=template_id for update; if old is null then raise exception 'TEMPLATE_NOT_FOUND'; end if; if not academic.valid_template_transition(old,target) then raise exception 'TEMPLATE_INVALID_STATE'; end if; if target in ('UNDER_REVIEW','APPROVED','ACTIVE') and not exists(select 1 from academic.schedule_template_blocks b where b.schedule_template_id=template_id and b.status='ACTIVE') then raise exception 'TEMPLATE_BLOCK_NOT_ALLOWED'; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.schedule_templates set status=target,approved_by_account_id=case when target='APPROVED' then actor else approved_by_account_id end,approved_at=case when target='APPROVED' then statement_timestamp() else approved_at end,updated_at=statement_timestamp() where id=template_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'TEMPLATE',template_id); perform academic.append_schedule_event('TEMPLATE',template_id,null,null,event,actor,old::text,target::text,case when target='APPROVED' then 'INSTITUTIONAL_APPROVAL'::academic.schedule_reason_code else 'SCHEDULE_OPERATION'::academic.schedule_reason_code end,operation_key,correlation); return query select template_id,target::text; end$$;
create function academic.submit_schedule_template(template_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_template_status(template_id,'UNDER_REVIEW','SUBMIT_SCHEDULE_TEMPLATE','TEMPLATE_SUBMITTED','academic.schedule_templates.manage',operation_key,correlation)$$;
create function academic.approve_schedule_template(template_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_template_status(template_id,'APPROVED','APPROVE_SCHEDULE_TEMPLATE','TEMPLATE_APPROVED','academic.schedule_templates.manage',operation_key,correlation)$$;
create function academic.activate_schedule_template(template_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_template_status(template_id,'ACTIVE','ACTIVATE_SCHEDULE_TEMPLATE','TEMPLATE_ACTIVATED','academic.schedule_templates.manage',operation_key,correlation)$$;
create function academic.retire_schedule_template(template_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_template_status(template_id,'RETIRED','RETIRE_SCHEDULE_TEMPLATE','TEMPLATE_RETIRED','academic.schedule_templates.manage',operation_key,correlation)$$;

create function academic.assert_active_teacher(teacher_id uuid) returns void language plpgsql stable security definer set search_path='' as $$begin if not exists(select 1 from core.accounts a join core.account_roles ar on ar.account_id=a.id and ar.revoked_at is null join core.roles r on r.id=ar.role_id and r.code='DOCENTE' and r.is_active where a.id=teacher_id and a.account_status='ACTIVE') then raise exception 'ASSIGNMENT_NOT_COMPATIBLE'; end if; end$$;
create function academic.declare_teacher_availability(teacher_id uuid,period_id uuid,weekday smallint,block_id uuid,kind academic.teacher_availability_type,valid_from date,valid_to date,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; begin actor:=academic.require_schedule_permission('academic.teacher_availability.manage'); prior:=academic.begin_schedule_command(actor,'DECLARE_TEACHER_AVAILABILITY',operation_key,jsonb_build_object('teacher',teacher_id,'period',period_id,'weekday',weekday,'block',block_id,'kind',kind,'from',valid_from,'to',valid_to)); if prior is not null then return query select prior,'ACTIVE'; return; end if; perform academic.assert_active_teacher(teacher_id); if weekday not between 1 and 7 or not exists(select 1 from academic.academic_periods p where p.id=period_id and p.status in ('PLANNED','ACTIVE')) or not exists(select 1 from academic.schedule_time_blocks b where b.id=block_id and b.status='ACTIVE') then raise exception 'TEACHER_AVAILABILITY_CONFLICT'; end if; insert into academic.teacher_availability(teacher_account_id,academic_period_id,weekday,time_block_id,availability_type,valid_from,valid_to,declared_by_account_id) values(teacher_id,period_id,weekday,block_id,kind,valid_from,valid_to,actor) returning id into created; perform academic.complete_schedule_command(actor,'DECLARE_TEACHER_AVAILABILITY',operation_key,'TEACHER_AVAILABILITY',created); perform academic.append_schedule_event('TEACHER_AVAILABILITY',created,null,period_id,'TEACHER_AVAILABILITY_DECLARED',actor,null,'ACTIVE','SCHEDULE_OPERATION',operation_key,correlation); return query select created,'ACTIVE'; end$$;
create function academic.cancel_teacher_availability(availability_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; item academic.teacher_availability%rowtype; begin actor:=academic.require_schedule_permission('academic.teacher_availability.manage'); prior:=academic.begin_schedule_command(actor,'CANCEL_TEACHER_AVAILABILITY',operation_key,jsonb_build_object('availability',availability_id)); if prior is not null then return query select prior,'CANCELLED'; return; end if; select * into item from academic.teacher_availability where id=availability_id for update; if item.id is null or item.status<>'ACTIVE' then raise exception 'TEACHER_AVAILABILITY_CONFLICT'; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.teacher_availability set status='CANCELLED',updated_at=statement_timestamp() where id=availability_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,'CANCEL_TEACHER_AVAILABILITY',operation_key,'TEACHER_AVAILABILITY',availability_id); perform academic.append_schedule_event('TEACHER_AVAILABILITY',availability_id,null,item.academic_period_id,'TEACHER_AVAILABILITY_CANCELLED',actor,'ACTIVE','CANCELLED','SCHEDULE_OPERATION',operation_key,correlation); return query select availability_id,'CANCELLED'; end$$;

create function academic.create_group_schedule(group_id uuid,template_id uuid,version integer,effective_from date,effective_to date,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; g academic.groups%rowtype; template academic.schedule_templates%rowtype; begin actor:=academic.require_schedule_permission('academic.schedules.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_GROUP_SCHEDULE',operation_key,jsonb_build_object('group',group_id,'template',template_id,'version',version,'from',effective_from,'to',effective_to)); if prior is not null then return query select prior,'DRAFT'; return; end if; perform pg_advisory_xact_lock(hashtextextended(group_id::text,0)); select * into g from academic.groups where id=group_id for update; select * into template from academic.schedule_templates where id=template_id for update; if g.id is null or g.status not in ('PLANNED','OPEN','ACTIVE') then raise exception 'GROUP_NOT_AVAILABLE'; end if; if template.id is null or template.status<>'ACTIVE' then raise exception 'TEMPLATE_INVALID_STATE'; end if; if version<=0 then raise exception 'GROUP_SCHEDULE_CONFLICT'; end if; insert into academic.group_schedules(group_id,academic_period_id,schedule_template_id,version_number,effective_from,effective_to,created_by_account_id) values(group_id,g.academic_period_id,template_id,version,effective_from,effective_to,actor) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_GROUP_SCHEDULE',operation_key,'GROUP_SCHEDULE',created); perform academic.append_schedule_event('GROUP_SCHEDULE',created,created,g.academic_period_id,'GROUP_SCHEDULE_CREATED',actor,null,'DRAFT','INITIAL_CONFIGURATION',operation_key,correlation); return query select created,'DRAFT'; end$$;

create function academic.validate_group_schedule_coverage(schedule_id uuid) returns table(valid boolean,missing_offering_count integer,conflict_count integer,invalid_session_count integer) language sql stable security definer set search_path='' as $$
with s as(select * from academic.group_schedules where id=schedule_id), active_offerings as(select o.id from academic.academic_offerings o join s on s.group_id=o.group_id and s.academic_period_id=o.academic_period_id where o.status='ACTIVE'), missing as(select count(*)::integer n from active_offerings o where not exists(select 1 from academic.class_sessions cs where cs.group_schedule_id=schedule_id and cs.academic_offering_id=o.id and cs.status in ('PLANNED','ACTIVE'))), invalid as(select count(*)::integer n from academic.class_sessions cs join s on s.id=cs.group_schedule_id left join academic.academic_offerings o on o.id=cs.academic_offering_id left join academic.teaching_assignments a on a.id=cs.teaching_assignment_id where cs.group_schedule_id=schedule_id and cs.status in ('PLANNED','ACTIVE') and (o.id is null or o.group_id<>s.group_id or o.academic_period_id<>s.academic_period_id or o.status<>'ACTIVE' or a.id is null or a.academic_offering_id<>o.id or a.status<>'ACTIVE')), conflicts as(select count(*)::integer n from academic.class_sessions a join academic.class_sessions b on a.id<b.id and a.group_schedule_id=b.group_schedule_id and a.weekday=b.weekday and a.time_block_id=b.time_block_id and a.status in ('PLANNED','ACTIVE') and b.status in ('PLANNED','ACTIVE') where a.group_schedule_id=schedule_id) select missing.n=0 and invalid.n=0 and conflicts.n=0,missing.n,conflicts.n,invalid.n from missing,invalid,conflicts$$;

create function academic.change_group_schedule_status(schedule_id uuid,target academic.group_schedule_status,command_name academic.schedule_command_type,event academic.schedule_event_type,permission text,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; current academic.group_schedules%rowtype; coverage record; begin actor:=academic.require_schedule_permission(permission); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('schedule',schedule_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into current from academic.group_schedules where id=schedule_id for update; if current.id is null then raise exception 'GROUP_SCHEDULE_NOT_FOUND'; end if; perform pg_advisory_xact_lock(hashtextextended(current.group_id::text,0)); if not academic.valid_group_schedule_transition(current.status,target) then raise exception 'GROUP_SCHEDULE_INVALID_STATE'; end if; if target in ('UNDER_REVIEW','APPROVED','PUBLISHED') then select * into coverage from academic.validate_group_schedule_coverage(schedule_id); if not coverage.valid then raise exception 'SCHEDULE_COVERAGE_INCOMPLETE'; end if; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.group_schedules set status=target,submitted_by_account_id=case when target='UNDER_REVIEW' then actor else submitted_by_account_id end,submitted_at=case when target='UNDER_REVIEW' then statement_timestamp() else submitted_at end,approved_by_account_id=case when target='APPROVED' then actor else approved_by_account_id end,approved_at=case when target='APPROVED' then statement_timestamp() else approved_at end,published_by_account_id=case when target='PUBLISHED' then actor else published_by_account_id end,published_at=case when target='PUBLISHED' then statement_timestamp() else published_at end,closed_by_account_id=case when target='CLOSED' then actor else closed_by_account_id end,closed_at=case when target='CLOSED' then statement_timestamp() else closed_at end,updated_at=statement_timestamp() where id=schedule_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'GROUP_SCHEDULE',schedule_id); perform academic.append_schedule_event('GROUP_SCHEDULE',schedule_id,schedule_id,current.academic_period_id,event,actor,current.status::text,target::text,case when target in ('APPROVED','PUBLISHED') then 'INSTITUTIONAL_APPROVAL'::academic.schedule_reason_code else 'SCHEDULE_OPERATION'::academic.schedule_reason_code end,operation_key,correlation); return query select schedule_id,target::text; end$$;
create function academic.submit_group_schedule(schedule_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_group_schedule_status(schedule_id,'UNDER_REVIEW','SUBMIT_GROUP_SCHEDULE','GROUP_SCHEDULE_SUBMITTED','academic.schedules.manage',operation_key,correlation)$$;
create function academic.approve_group_schedule(schedule_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_group_schedule_status(schedule_id,'APPROVED','APPROVE_GROUP_SCHEDULE','GROUP_SCHEDULE_APPROVED','academic.schedules.approve',operation_key,correlation)$$;
create function academic.publish_group_schedule(schedule_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_group_schedule_status(schedule_id,'PUBLISHED','PUBLISH_GROUP_SCHEDULE','GROUP_SCHEDULE_PUBLISHED','academic.schedules.publish',operation_key,correlation)$$;
create function academic.close_group_schedule(schedule_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_group_schedule_status(schedule_id,'CLOSED','CLOSE_GROUP_SCHEDULE','GROUP_SCHEDULE_CLOSED','academic.schedules.manage',operation_key,correlation)$$;
create function academic.cancel_group_schedule(schedule_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_group_schedule_status(schedule_id,'CANCELLED','CANCEL_GROUP_SCHEDULE','GROUP_SCHEDULE_CANCELLED','academic.schedules.manage',operation_key,correlation)$$;

create function academic.validate_schedule_conflicts(schedule_id uuid,offering_id uuid,assignment_id uuid,space_id uuid,weekday smallint,block_id uuid,session_id uuid default null) returns table(valid boolean,error_code text) language plpgsql stable security definer set search_path='' as $$declare s academic.group_schedules%rowtype; o academic.academic_offerings%rowtype; a academic.teaching_assignments%rowtype; sp academic.academic_spaces%rowtype; b academic.schedule_time_blocks%rowtype; teacher uuid; period_status academic.structure_status; begin select * into s from academic.group_schedules where id=schedule_id; if s.id is null then return query select false,'GROUP_SCHEDULE_NOT_FOUND'; return; end if; select p.status into period_status from academic.academic_periods p where p.id=s.academic_period_id; if period_status='CLOSING' then return query select false,'PERIOD_CLOSING'; return; elsif period_status not in ('PLANNED','ACTIVE') then return query select false,'PERIOD_NOT_AVAILABLE'; return; end if; select * into o from academic.academic_offerings where id=offering_id; if o.id is null or o.group_id<>s.group_id or o.academic_period_id<>s.academic_period_id or o.status<>'ACTIVE' then return query select false,'OFFERING_NOT_COMPATIBLE'; return; end if; select * into a from academic.teaching_assignments where id=assignment_id; if a.id is null or a.academic_offering_id<>offering_id then return query select false,'ASSIGNMENT_NOT_COMPATIBLE'; return; end if; if a.status<>'ACTIVE' then return query select false,'ASSIGNMENT_NOT_ACTIVE'; return; end if; teacher:=a.teacher_account_id; if not exists(select 1 from core.accounts ac join core.account_roles ar on ar.account_id=ac.id and ar.revoked_at is null join core.roles r on r.id=ar.role_id and r.code='DOCENTE' where ac.id=teacher and ac.account_status='ACTIVE') then return query select false,'ASSIGNMENT_NOT_COMPATIBLE'; return; end if; select * into sp from academic.academic_spaces where id=space_id; if sp.id is null or sp.status<>'ACTIVE' then return query select false,'SPACE_NOT_AVAILABLE'; return; end if; select * into b from academic.schedule_time_blocks where id=block_id; if b.id is null or b.status<>'ACTIVE' then return query select false,'TIME_BLOCK_NOT_FOUND'; return; end if; if b.is_break then return query select false,'TIME_BLOCK_IS_BREAK'; return; end if; if not exists(select 1 from academic.schedule_template_blocks tb where tb.schedule_template_id=s.schedule_template_id and tb.weekday=validate_schedule_conflicts.weekday and tb.time_block_id=block_id and tb.status='ACTIVE') then return query select false,'TEMPLATE_BLOCK_NOT_ALLOWED'; return; end if; if sp.space_type<>'LABORATORY' and exists(select 1 where false) then null; end if; if exists(select 1 from academic.teacher_availability av where av.teacher_account_id=teacher and av.academic_period_id=s.academic_period_id and av.weekday=validate_schedule_conflicts.weekday and av.time_block_id=block_id and av.status='ACTIVE' and av.availability_type='UNAVAILABLE' and (av.valid_from is null or av.valid_from<=coalesce(s.effective_to,av.valid_from)) and (av.valid_to is null or av.valid_to>=coalesce(s.effective_from,av.valid_to))) then return query select false,'TEACHER_UNAVAILABLE'; return; end if; if exists(select 1 from academic.class_sessions cs join academic.group_schedules gs on gs.id=cs.group_schedule_id where cs.id is distinct from session_id and gs.group_id=s.group_id and gs.academic_period_id=s.academic_period_id and cs.weekday=validate_schedule_conflicts.weekday and cs.time_block_id=block_id and cs.status in ('PLANNED','ACTIVE')) then return query select false,'GROUP_TIME_CONFLICT'; return; end if; if exists(select 1 from academic.class_sessions cs join academic.group_schedules gs on gs.id=cs.group_schedule_id join academic.teaching_assignments ta on ta.id=cs.teaching_assignment_id where cs.id is distinct from session_id and ta.teacher_account_id=teacher and gs.academic_period_id=s.academic_period_id and cs.weekday=validate_schedule_conflicts.weekday and cs.time_block_id=block_id and cs.status in ('PLANNED','ACTIVE')) then return query select false,'TEACHER_TIME_CONFLICT'; return; end if; if exists(select 1 from academic.class_sessions cs join academic.group_schedules gs on gs.id=cs.group_schedule_id where cs.id is distinct from session_id and cs.academic_space_id=space_id and gs.academic_period_id=s.academic_period_id and cs.weekday=validate_schedule_conflicts.weekday and cs.time_block_id=block_id and cs.status in ('PLANNED','ACTIVE')) then return query select false,'SPACE_TIME_CONFLICT'; return; end if; return query select true,null::text; end$$;

create function academic.create_class_session(schedule_id uuid,offering_id uuid,assignment_id uuid,space_id uuid,weekday smallint,block_id uuid,kind academic.class_session_type,valid_from date,valid_to date,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; check_result record; schedule academic.group_schedules%rowtype; begin actor:=academic.require_schedule_permission('academic.schedules.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_CLASS_SESSION',operation_key,jsonb_build_object('schedule',schedule_id,'offering',offering_id,'assignment',assignment_id,'space',space_id,'weekday',weekday,'block',block_id,'kind',kind,'from',valid_from,'to',valid_to)); if prior is not null then return query select prior,'PLANNED'; return; end if; select * into schedule from academic.group_schedules where id=schedule_id for update; if schedule.id is null then raise exception 'GROUP_SCHEDULE_NOT_FOUND'; end if; if schedule.status not in ('DRAFT','UNDER_REVIEW','APPROVED') then raise exception 'PUBLISHED_SCHEDULE_IMMUTABLE'; end if; perform pg_advisory_xact_lock(hashtextextended(schedule.academic_period_id::text||weekday::text||block_id::text,0)); perform 1 from academic.academic_spaces where id=space_id for update; perform 1 from academic.teaching_assignments where id=assignment_id for update; select * into check_result from academic.validate_schedule_conflicts(schedule_id,offering_id,assignment_id,space_id,weekday,block_id,null); if not check_result.valid then raise exception '%',check_result.error_code; end if; if kind='LABORATORY' and not exists(select 1 from academic.academic_spaces where id=space_id and space_type='LABORATORY') then raise exception 'SPACE_TYPE_NOT_COMPATIBLE'; end if; insert into academic.class_sessions(group_schedule_id,academic_offering_id,teaching_assignment_id,academic_space_id,weekday,time_block_id,session_type,valid_from,valid_to,created_by_account_id) values(schedule_id,offering_id,assignment_id,space_id,weekday,block_id,kind,valid_from,valid_to,actor) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_CLASS_SESSION',operation_key,'CLASS_SESSION',created); perform academic.append_schedule_event('CLASS_SESSION',created,schedule_id,schedule.academic_period_id,'CLASS_SESSION_CREATED',actor,null,'PLANNED','SCHEDULE_OPERATION',operation_key,correlation); return query select created,'PLANNED'; end$$;

create function academic.change_class_session_status(session_id uuid,target academic.class_session_status,command_name academic.schedule_command_type,event academic.schedule_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; item academic.class_sessions%rowtype; schedule academic.group_schedules%rowtype; check_result record; begin actor:=academic.require_schedule_permission('academic.schedules.manage'); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('session',session_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into item from academic.class_sessions where id=session_id for update; if item.id is null then raise exception 'CLASS_SESSION_NOT_FOUND'; end if; select * into schedule from academic.group_schedules where id=item.group_schedule_id for update; if not academic.valid_class_session_transition(item.status,target) then raise exception 'CLASS_SESSION_INVALID_STATE'; end if; if target='ACTIVE' then perform 1 from academic.teaching_assignments where id=item.teaching_assignment_id for update; perform 1 from academic.academic_spaces where id=item.academic_space_id for update; select * into check_result from academic.validate_schedule_conflicts(item.group_schedule_id,item.academic_offering_id,item.teaching_assignment_id,item.academic_space_id,item.weekday,item.time_block_id,item.id); if not check_result.valid then raise exception '%',check_result.error_code; end if; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.class_sessions set status=target,cancelled_by_account_id=case when target='CANCELLED' then actor else cancelled_by_account_id end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,updated_at=statement_timestamp() where id=session_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'CLASS_SESSION',session_id); perform academic.append_schedule_event('CLASS_SESSION',session_id,item.group_schedule_id,schedule.academic_period_id,event,actor,item.status::text,target::text,'SCHEDULE_OPERATION',operation_key,correlation); return query select session_id,target::text; end$$;
create function academic.activate_class_session(session_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_class_session_status(session_id,'ACTIVE','ACTIVATE_CLASS_SESSION','CLASS_SESSION_ACTIVATED',operation_key,correlation)$$;
create function academic.cancel_class_session(session_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_class_session_status(session_id,'CANCELLED','CANCEL_CLASS_SESSION','CLASS_SESSION_CANCELLED',operation_key,correlation)$$;
create function academic.end_class_session(session_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_class_session_status(session_id,'ENDED','END_CLASS_SESSION','CLASS_SESSION_ENDED',operation_key,correlation)$$;

create function academic.change_class_session_slot(session_id uuid,new_weekday smallint,new_block_id uuid,new_space_id uuid,new_assignment_id uuid,change_id uuid,command_name academic.schedule_command_type,event academic.schedule_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; item academic.class_sessions%rowtype; schedule academic.group_schedules%rowtype; check_result record; final_weekday smallint; final_block uuid; final_space uuid; final_assignment uuid; begin actor:=academic.require_schedule_permission('academic.schedule_changes.manage'); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('session',session_id,'weekday',new_weekday,'block',new_block_id,'space',new_space_id,'assignment',new_assignment_id,'change',change_id)); if prior is not null then return query select prior,'ACTIVE'; return; end if; select * into item from academic.class_sessions where id=session_id for update; if item.id is null or item.status not in ('PLANNED','ACTIVE') then raise exception 'CLASS_SESSION_INVALID_STATE'; end if; select * into schedule from academic.group_schedules where id=item.group_schedule_id for update; if schedule.status in ('PUBLISHED','CLOSED') and not exists(select 1 from academic.schedule_change_requests c where c.id=change_id and c.group_schedule_id=schedule.id and c.status='APPROVED') then raise exception 'PUBLISHED_SCHEDULE_IMMUTABLE'; end if; final_weekday:=coalesce(new_weekday,item.weekday); final_block:=coalesce(new_block_id,item.time_block_id); final_space:=coalesce(new_space_id,item.academic_space_id); final_assignment:=coalesce(new_assignment_id,item.teaching_assignment_id); perform pg_advisory_xact_lock(hashtextextended(schedule.academic_period_id::text||final_weekday::text||final_block::text,0)); select * into check_result from academic.validate_schedule_conflicts(item.group_schedule_id,item.academic_offering_id,final_assignment,final_space,final_weekday,final_block,item.id); if not check_result.valid then raise exception '%',check_result.error_code; end if; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.class_sessions set weekday=final_weekday,time_block_id=final_block,academic_space_id=final_space,teaching_assignment_id=final_assignment,updated_at=statement_timestamp() where id=session_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'CLASS_SESSION',session_id); perform academic.append_schedule_event('CLASS_SESSION',session_id,item.group_schedule_id,schedule.academic_period_id,event,actor,item.status::text,item.status::text,'CORRECTIVE_CHANGE',operation_key,correlation); return query select session_id,item.status::text; end$$;
create function academic.move_class_session(session_id uuid,new_weekday smallint,new_block_id uuid,change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_class_session_slot(session_id,new_weekday,new_block_id,null,null,change_id,'MOVE_CLASS_SESSION','CLASS_SESSION_MOVED',operation_key,correlation)$$;
create function academic.change_class_session_space(session_id uuid,new_space_id uuid,change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_class_session_slot(session_id,null,null,new_space_id,null,change_id,'CHANGE_CLASS_SESSION_SPACE','CLASS_SESSION_SPACE_CHANGED',operation_key,correlation)$$;
create function academic.change_class_session_assignment(session_id uuid,new_assignment_id uuid,change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_class_session_slot(session_id,null,null,null,new_assignment_id,change_id,'CHANGE_CLASS_SESSION_ASSIGNMENT','CLASS_SESSION_ASSIGNMENT_CHANGED',operation_key,correlation)$$;

create function academic.create_schedule_change_request(schedule_id uuid,kind academic.schedule_change_type,reason academic.schedule_reason_code,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; schedule academic.group_schedules%rowtype; fingerprint text; begin actor:=academic.require_schedule_permission('academic.schedule_changes.manage'); prior:=academic.begin_schedule_command(actor,'CREATE_SCHEDULE_CHANGE_REQUEST',operation_key,jsonb_build_object('schedule',schedule_id,'kind',kind,'reason',reason)); if prior is not null then return query select prior,'DRAFT'; return; end if; select * into schedule from academic.group_schedules where id=schedule_id for update; if schedule.id is null then raise exception 'GROUP_SCHEDULE_NOT_FOUND'; end if; fingerprint:=academic.schedule_fingerprint(jsonb_build_object('schedule',schedule_id,'kind',kind,'reason',reason)); insert into academic.schedule_change_requests(group_schedule_id,request_type,reason_code,requested_by_account_id,idempotency_key,request_fingerprint) values(schedule_id,kind,reason,actor,operation_key,fingerprint) returning id into created; perform academic.complete_schedule_command(actor,'CREATE_SCHEDULE_CHANGE_REQUEST',operation_key,'SCHEDULE_CHANGE',created); perform academic.append_schedule_event('SCHEDULE_CHANGE',created,schedule_id,schedule.academic_period_id,'SCHEDULE_CHANGE_REQUESTED',actor,null,'DRAFT',reason,operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.change_schedule_request_status(change_id uuid,target academic.schedule_change_status,command_name academic.schedule_command_type,event academic.schedule_event_type,permission text,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; item academic.schedule_change_requests%rowtype; period_id uuid; begin actor:=academic.require_schedule_permission(permission); prior:=academic.begin_schedule_command(actor,command_name,operation_key,jsonb_build_object('change',change_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into item from academic.schedule_change_requests where id=change_id for update; if item.id is null then raise exception 'SCHEDULE_CHANGE_NOT_FOUND'; end if; if not academic.valid_schedule_change_transition(item.status,target) then raise exception 'SCHEDULE_CHANGE_INVALID_STATE'; end if; select academic_period_id into period_id from academic.group_schedules where id=item.group_schedule_id; perform set_config('academic.schedule_controlled_mutation','on',true); update academic.schedule_change_requests set status=target,reviewed_by_account_id=case when target='UNDER_REVIEW' then actor else reviewed_by_account_id end,reviewed_at=case when target='UNDER_REVIEW' then statement_timestamp() else reviewed_at end,approved_by_account_id=case when target='APPROVED' then actor else approved_by_account_id end,approved_at=case when target='APPROVED' then statement_timestamp() else approved_at end,applied_by_account_id=case when target='APPLIED' then actor else applied_by_account_id end,applied_at=case when target='APPLIED' then statement_timestamp() else applied_at end,rejected_at=case when target='REJECTED' then statement_timestamp() else rejected_at end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,updated_at=statement_timestamp() where id=change_id; perform set_config('academic.schedule_controlled_mutation','off',true); perform academic.complete_schedule_command(actor,command_name,operation_key,'SCHEDULE_CHANGE',change_id); perform academic.append_schedule_event('SCHEDULE_CHANGE',change_id,item.group_schedule_id,period_id,event,actor,item.status::text,target::text,item.reason_code,operation_key,correlation); return query select change_id,target::text; end$$;
create function academic.submit_schedule_change_request(change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_schedule_request_status(change_id,'SUBMITTED','SUBMIT_SCHEDULE_CHANGE_REQUEST','SCHEDULE_CHANGE_SUBMITTED','academic.schedule_changes.manage',operation_key,correlation)$$;
create function academic.begin_schedule_change_review(change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_schedule_request_status(change_id,'UNDER_REVIEW','BEGIN_SCHEDULE_CHANGE_REVIEW','SCHEDULE_CHANGE_REVIEW_STARTED','academic.schedule_changes.approve',operation_key,correlation)$$;
create function academic.approve_schedule_change_request(change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_schedule_request_status(change_id,'APPROVED','APPROVE_SCHEDULE_CHANGE_REQUEST','SCHEDULE_CHANGE_APPROVED','academic.schedule_changes.approve',operation_key,correlation)$$;
create function academic.reject_schedule_change_request(change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_schedule_request_status(change_id,'REJECTED','REJECT_SCHEDULE_CHANGE_REQUEST','SCHEDULE_CHANGE_REJECTED','academic.schedule_changes.approve',operation_key,correlation)$$;
create function academic.apply_schedule_change_request(change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_schedule_request_status(change_id,'APPLIED','APPLY_SCHEDULE_CHANGE_REQUEST','SCHEDULE_CHANGE_APPLIED','academic.schedule_changes.manage',operation_key,correlation)$$;
create function academic.cancel_schedule_change_request(change_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_schedule_request_status(change_id,'CANCELLED','CANCEL_SCHEDULE_CHANGE_REQUEST','SCHEDULE_CHANGE_CANCELLED','academic.schedule_changes.manage',operation_key,correlation)$$;

create function academic.get_teacher_workload_summary(teacher_id uuid,period_id uuid) returns table(offering_count integer,group_count integer,weekly_session_count integer,weekly_minutes integer,distribution_by_day jsonb,conflict_count integer,active_session_count integer,planned_session_count integer) language plpgsql stable security definer set search_path='' as $$begin perform academic.require_schedule_permission('academic.workload.read'); return query with base as(select cs.*,o.group_id,(extract(epoch from (b.ends_at-b.starts_at))/60)::integer minutes from academic.class_sessions cs join academic.teaching_assignments a on a.id=cs.teaching_assignment_id join academic.academic_offerings o on o.id=cs.academic_offering_id join academic.schedule_time_blocks b on b.id=cs.time_block_id where a.teacher_account_id=teacher_id and o.academic_period_id=period_id and cs.status in ('PLANNED','ACTIVE')), conflicts as(select count(*)::integer n from base a join base b on a.id<b.id and a.weekday=b.weekday and a.time_block_id=b.time_block_id), dist as(select coalesce(jsonb_object_agg(weekday,n),'{}'::jsonb) value from(select weekday,count(*) n from base group by weekday)x) select count(distinct academic_offering_id)::integer,count(distinct group_id)::integer,count(*)::integer,coalesce(sum(minutes),0)::integer,dist.value,conflicts.n,count(*) filter(where status='ACTIVE')::integer,count(*) filter(where status='PLANNED')::integer from base,conflicts,dist group by dist.value,conflicts.n; end$$;
create function academic.validate_teacher_workload(teacher_id uuid,period_id uuid) returns table(valid boolean,conflict_count integer,unavailable_count integer,invalid_assignment_count integer) language sql stable security definer set search_path='' as $$with base as(select cs.*,a.teacher_account_id,a.status assignment_status,o.academic_period_id from academic.class_sessions cs join academic.teaching_assignments a on a.id=cs.teaching_assignment_id join academic.academic_offerings o on o.id=cs.academic_offering_id where a.teacher_account_id=teacher_id and o.academic_period_id=period_id and cs.status in ('PLANNED','ACTIVE')), conflicts as(select count(*)::integer n from base a join base b on a.id<b.id and a.weekday=b.weekday and a.time_block_id=b.time_block_id), unavailable as(select count(*)::integer n from base b join academic.teacher_availability av on av.teacher_account_id=b.teacher_account_id and av.academic_period_id=b.academic_period_id and av.weekday=b.weekday and av.time_block_id=b.time_block_id and av.status='ACTIVE' and av.availability_type='UNAVAILABLE'), invalid as(select count(*)::integer n from base where assignment_status<>'ACTIVE') select conflicts.n=0 and unavailable.n=0 and invalid.n=0,conflicts.n,unavailable.n,invalid.n from conflicts,unavailable,invalid$$;

create function academic.enforce_class_session_conflicts() returns trigger language plpgsql security invoker set search_path='' as $$declare v_period_id uuid; v_group_id uuid; v_teacher_id uuid; begin if new.status not in ('PLANNED','ACTIVE') then return new; end if; select gs.academic_period_id,gs.group_id into v_period_id,v_group_id from academic.group_schedules gs where gs.id=new.group_schedule_id; select ta.teacher_account_id into v_teacher_id from academic.teaching_assignments ta where ta.id=new.teaching_assignment_id; perform pg_advisory_xact_lock(hashtextextended('schedule-slot:'||v_period_id::text||':'||new.weekday::text||':'||new.time_block_id::text,0)); if exists(select 1 from academic.class_sessions cs join academic.group_schedules gs on gs.id=cs.group_schedule_id where cs.id<>new.id and gs.academic_period_id=v_period_id and gs.group_id=v_group_id and cs.weekday=new.weekday and cs.time_block_id=new.time_block_id and cs.status in ('PLANNED','ACTIVE')) then raise exception 'GROUP_TIME_CONFLICT'; end if; if exists(select 1 from academic.class_sessions cs join academic.group_schedules gs on gs.id=cs.group_schedule_id join academic.teaching_assignments ta on ta.id=cs.teaching_assignment_id where cs.id<>new.id and gs.academic_period_id=v_period_id and ta.teacher_account_id=v_teacher_id and cs.weekday=new.weekday and cs.time_block_id=new.time_block_id and cs.status in ('PLANNED','ACTIVE')) then raise exception 'TEACHER_TIME_CONFLICT'; end if; if exists(select 1 from academic.class_sessions cs join academic.group_schedules gs on gs.id=cs.group_schedule_id where cs.id<>new.id and gs.academic_period_id=v_period_id and cs.academic_space_id=new.academic_space_id and cs.weekday=new.weekday and cs.time_block_id=new.time_block_id and cs.status in ('PLANNED','ACTIVE')) then raise exception 'SPACE_TIME_CONFLICT'; end if; return new; end$$;
create trigger class_sessions_conflict_barrier before insert or update on academic.class_sessions for each row execute function academic.enforce_class_session_conflicts();
create function academic.prevent_ending_assignment_with_active_session() returns trigger language plpgsql security invoker set search_path='' as $$begin if old.status='ACTIVE' and new.status='ENDED' then perform pg_advisory_xact_lock(hashtextextended('assignment:'||new.id::text,0)); if exists(select 1 from academic.class_sessions where teaching_assignment_id=new.id and status='ACTIVE') then raise exception 'ASSIGNMENT_NOT_ACTIVE'; end if; end if; return new; end$$;
create trigger teaching_assignments_schedule_guard before update on academic.teaching_assignments for each row execute function academic.prevent_ending_assignment_with_active_session();

revoke execute on all functions in schema academic from public,anon,authenticated;

commit;
